export interface HotelOption {
  id: string;
  cityId: string;
  name: string;
  nameEn: string;
  photo: string;
  starRating: number;
  reviewCount: number;
  pricePerNight: number;
  address: string;
  proximityNote: string;
  freeCancellation: boolean;
  breakfastIncluded: boolean;
  bookingUrl: string;
  latitude: number;
  longitude: number | null;
  tagline: string;
  distanceScore: number;
  nightlifeScore: number;
}

export interface FlightOption {
  id: string;
  cityId: string;
  airline: string;
  airlineCode: string;
  departureAirport: string;
  arrivalAirport: string;
  departureTime: string;
  arrivalTime: string;
  durationText: string;
  durationMinutes: number;
  isDirect: boolean;
  baggageInfo: string;
  price: number;
  bookingUrl: string;
}

