export function getHotelsForCity(cityId: string): HotelOption[] {
  if (hotelDatabase[cityId]) {
    return hotelDatabase[cityId];
  }
  return hotelDatabase["도쿄"] || [];
}

export function getFlightsForCity(cityId: string): FlightOption[] {
  if (flightDatabase[cityId]) {
    return flightDatabase[cityId];
  }
  return flightDatabase["도쿄"] || [];
}
